solution.sanitized:
def cursor_page(items, cursor, size):
    if size <= 0 or not 0 <= cursor <= len(items):
        raise ValueError("pagination")
    stop = min(len(items), cursor + size)
    return list(items[cursor:stop]), stop if stop < len(items) else None

